    103: {'name': 'Notebook', 'price': 5.0, 'tags': ['stationery', 'sale']}
}

def apply_sale_discounts(catalog):
    updated = {}
    for pid, info in catalog.items():
        new_info = info.copy()
        if 'sale' in new_info['tags']:
            new_info['price'] = round(new_info['price'] * 0.9, 2)
        updated[pid] = new_info
    return updated

print(apply_sale_discounts(products))

