org_chart = {
    'Engineering': {
        'Alice': {'python': 5, 'sql': 4},
        'Bob': {'python': 4, 'docker': 3}
    },
    'Marketing': {
        'Carol': {'seo': 5, 'analytics': 4, 'content': 3},
        'Dave': {'seo': 2, 'content': 4}
    }
}

def total_proficiency(chart):
    total = 0
    for department in chart.values():
        for employee in department.values():
            total += sum(employee.values())
    return total

print(total_proficiency(org_chart))
